entries[90418] = { ["name"] = "Volcanic Skybox" }
entries[90419] = { ["name"] = "Eisensterns versteinerter Schild", ["text"] = "Wirken in 2 sek. 5\nDer Legende nach schnitzte der Dunkeleisenthan Eisenstern diesen Schild aus dem Holz eines heiligen Baumes der Hochelfen und verzauberte ihn, auf dass er so hart wie Stein werde.\nEisensterns versteinerter Schild\nWird beim Aufheben gebunden" }
entries[90420] = { ["name"] = "Schädelförmiger Blumentopf", ["text"] = "Wirken in 2 sek. 5\nWaldtrolle haben eine starke Affinität zur umgebenden Flora. Die Körper der Trolle selbst können Heimat simpler Pflanzenkulturen sein, zum Beispiel von Moosen oder Algen, was ihnen ihre charakteristische grüne Farbschattierung verleiht.\nSchädelförmiger Blumentopf\nWird beim Aufheben gebunden" }
entries[90421] = { ["name"] = "Jadearmband mit Münzen", ["text"] = "Wirken in 2 sek. 5\nDieses Armband besteht aus einem Silberkettchen, an dem polierte Jadesteine und trollische Münzen befestigt sind. Da Trolle eher Gold als Schmuckmaterial bevorzugen, ist es möglich, dass das Silber von einem anderen Volk erbeutet wurde - was wiederum bedeutet, dass dieser Fund jüngeren Ursprungs ist. Die Münzen sind ungewöhnlich, auf jeder ist das Gesicht einer anderen Trollfrau dargestellt.\nJadearmband mit Münzen\nWird beim Aufheben gebunden" }
entries[90422] = { ["name"] = "Kolossales Spalten" }
entries[90423] = { ["name"] = "Figur von Gahz'rilla", ["text"] = "Wirken in 2 sek. 5\nDie Sandtrolle beschworen diese gewaltige weiße Hydra aus einem heiligen Wasserbecken in Zul'Farrak und verehrten sie daraufhin als Gottheit. Gahz'rillas Schuppen sind elektrisch aufgeladen und selbst diese kleine Figur knistert vor Energie. Innerhalb von Zul'Farrak ist die legendäre Hydra ein häufig auftretendes architektonisches und ornamentales Motiv.\nFigur von Gahz'rilla\nWird beim Aufheben gebunden" }
