entries[90432] = { ["name"] = "Zahn eines Teufelssauriers", ["text"] = "Wirken in 2 sek. 5\nTeufelssaurier sind die größte Raubtierart, die jemals auf Azeroth lebte. Auch wenn der Großteil vor langer Zeit ausstarb, gedeihen wenige Exemplare weiterhin in isolierten Gebieten. Es gibt viele Spekulationen über den Zweck der verkümmerten Arme der Teufelssaurier. Eine Theorie lautet, dass sie ihnen beim Aufstehen behilflich sind. Eine andere, dass sie dazu dienen, Weibchen zu kitzeln. Weitere Beobachtungen sind erforderlich.\nZahn eines Teufelssauriers\nWird beim Aufheben gebunden" }
entries[90433] = { ["name"] = "In Bernstein eingeschlossenes Insekt", ["text"] = "Wirken in 2 sek. 5\nBernstein ist versteinertes Baumharz. Einer der Zwecke von Baumharz besteht darin, den Baum vor Schädlingen zu schützen. Daher kann es vorkommen, dass einige seltene Bernsteine von ihrem Harz umschlossene Insekten beinhalten.\nIn Bernstein eingeschlossenes Insekt\nWird beim Aufheben gebunden" }
