entries[90488] = { ["name"] = "Wyverngift", ["text"] = "205 Mana 35 Meter Reichweite\nSofort\nVerschießt einen Stachel, der das Ziel 10 Sek. lang einschläfert. Jeglicher erlittene Schaden hebt den Effekt wieder auf. Wenn das Ziel wieder aufwacht, verursacht das Stachelgift 12 Sek. lang Naturschaden." }
