entries[90511] = { ["name"] = "Invisibility Detection Quest 25" }
entries[90518] = { ["name"] = "Mithrilkette von Zornesschmied", ["text"] = "Wirken in 2 sek. 5\nDie Familienlinie der Zornesschmied durchzieht die gesamte Geschichte der Dunkeleisenzwerge. Das ist eine Kette, die von Than Zornesschmied getragen wurde, dem Vorfahren von General Zornesschmied, der noch immer die Armeen des Dunkeleisenklans im Schwarzfels befehligt.\nMithrilkette von Zornesschmied\nWird beim Aufheben gebunden" }
entries[90519] = { ["name"] = "Schädelstab von Schattenschmiede", ["text"] = "Wirken in 2 sek. 5\nDie Familie Schattenschmiede hinterließ einen Schandfleck auf der Geschichte der Dunkeleisenzwerge. Eisenthan Schattenschmiede war allen Berichten zufolge ein grausamer Despot, der viele seiner eigenen Untertanen folterte und tötete. Allgemein wird angenommen, er sei ein Hexenmeister gewesen, dennoch halten sich hartnäckige Gerüchte, dass er einer der ersten zwergischen Schamanen war.\nSchädelstab von Schattenschmiede\nWird beim Aufheben gebunden" }
entries[90520] = { ["name"] = "Arkane Überladung" }
entries[90521] = { ["name"] = "Aufziehgnom", ["text"] = "Wirken in 2 sek. 15\nMechagnome wurden von den Titanen erschaffen und sie fungierten, ähnlich wie die Irdenen, als Diener und Hüter. Dieser Mechagnom wurde vermutlich beschädigt, denn statt seiner ursprüngliche Aufgabe nachzugehen scheint er ganz damit zufrieden zu sein, Euch einfach nur nachzulaufen.\nAufziehgnom\nWird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Aufziehgnom beschwören oder wieder freigeben.\n1 - 80 ( 80)" }
entries[90522] = { ["name"] = "Wasserhülle", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nAbsorbiert 189 Schaden. Wenn die Wasserhülle bricht, explodiert sie und fügt Feinden in einem Umkreis von 8 Metern 57 Frostschaden zu." }
entries[90523] = { ["name"] = "Aufziehgnom", ["text"] = "Sofort\nMit Rechtsklick Euren Aufziehgnom beschwören oder wieder freigeben." }
entries[90524] = { ["name"] = "Wasserexplosion", ["text"] = "40 Meter Reichweite\nSofort\nFügt allen Gegnern innerhalb von 8 Metern 57 Frostschaden zu." }
entries[90528] = { ["name"] = "See Quest Invis 5" }
entries[90546] = { ["name"] = "Trampelschutz", ["text"] = "Sofort\nVom mächtigen Olaf beschützt. Helix kann nicht sterben, solange sein Trampel ihn beschützt." }
entries[90550] = { ["name"] = "Arkanbeschuss", ["text"] = "100 Mana 30 Meter Reichweite\nWirken in 2 sek.\nSchleudert mehrere Geschosse auf das feindliche Ziel und verursacht Arkanschaden." }
entries[90551] = { ["name"] = "Überwältigende Kraft", ["text"] = "100 Meter Reichweite\nWirken in 5 sek.\nSendet einen Magiebogen aus, der bei dem ausgewählten Feind Arkanschaden verursacht." }
entries[90553] = { ["name"] = "Kelch der Bergkönige", ["text"] = "Wirken in 2 sek. 15\nZusätzlich zum dichten Edelsteinzierrat ist dieser Kelch über und über mit Runen bedeckt, welche die Thronfolgezeremonie eines Zwergenkönigs rühmen. Obwohl es sicherlich Teil dieser Zeremonie war, aus diesem Kelch zu trinken, beschreiben die Runen dennoch einen \"Schwerttanz\", der von Zwergenkriegerinnen dargeboten wurde. Diese Aufführung - teils Ritual, teils Schaukampf - entwickelte sich aus blutigen Duellen, die einst in weniger kultivierten Zeitaltern der zwergischen Geschichte stattfanden.\nKelch der Bergkönige\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Werdet Zeuge eines historischen Schwerttanzes. (10 Min Abklingzeit)" }
